import AppKit

// pasteboard sync; owns local writes to suppress echo
final class Clipboard {
    private let pb = NSPasteboard.general
    private var lastCount: Int
    private var timer: Timer?

    private static let skip: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    var onLocal: ((Header, Data) -> Void)?
    var onLocalFiles: (([URL]) -> Void)?

    init() { lastCount = pb.changeCount }

    func start() {
        lastCount = pb.changeCount   // ignore pre-link clipboard, even on re-arm
        guard timer == nil else { return }
        let t = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    func stop() { timer?.invalidate(); timer = nil }

    private func poll() {
        let c = pb.changeCount
        guard c != lastCount else { return }
        lastCount = c

        let types = pb.types?.map(\.rawValue) ?? []
        if types.contains(where: Self.skip.contains) { return }

        if let urls = pb.readObjects(forClasses: [NSURL.self],
                                     options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            onLocalFiles?(urls)
        } else if let data = imageData() {
            onLocal?(Header(kind: Kind.image, name: nil, device: nil), data)
        } else if let s = pb.string(forType: .string), !s.isEmpty {
            onLocal?(Header(kind: Kind.text, name: nil, device: nil), Data(s.utf8))
        }
    }

    private func imageData() -> Data? {
        if let png = pb.data(forType: .png) { return png }
        guard let tiff = pb.data(forType: .tiff),
              let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }

    func apply(_ header: Header, _ payload: Data, saveDir: URL) {
        switch header.kind {
        case Kind.text:
            pb.clearContents(); pb.setString(String(decoding: payload, as: UTF8.self), forType: .string)
        case Kind.image:
            pb.clearContents(); pb.setData(payload, forType: .png)
        case Kind.file:
            guard let url = Files.save(payload, name: header.name ?? "file", in: saveDir) else { return }
            pb.clearContents(); pb.writeObjects([url as NSURL])
        default:
            return
        }
        lastCount = pb.changeCount   // suppress our own echo
    }
}
